-- Add concrete home/gym alternatives and explicit replacement eligibility metadata.
-- Reference-only changes. No user/session/history or legacy engine behavior is changed.
begin;
create temporary table replacement_additions(entry jsonb not null) on commit drop;
select entry->>'slug',entry->>'name',entry->>'movement_pattern',entry->'equipment',(entry->>'is_bodyweight')::boolean,entry->'aliases',entry->'tags',entry->'media',entry->'contraindications',true,entry->>'category',entry->>'tracking_mode',entry->'instructions',entry->'source_urls',entry->>'review_status',entry->>'catalog_notes' from replacement_additions
on conflict(slug) do update set name=excluded.name,movement_pattern=excluded.movement_pattern,equipment=excluded.equipment,is_bodyweight=excluded.is_bodyweight,aliases=excluded.aliases,tags=excluded.tags,category=excluded.category,tracking_mode=excluded.tracking_mode,instructions=excluded.instructions,source_urls=excluded.source_urls,review_status=excluded.review_status,catalog_notes=excluded.catalog_notes;
delete from public.exercise_muscle_map em using public.exercises e,replacement_additions r where em.exercise_id=e.id and e.slug=r.entry->>'slug';
select e.id,m.id,x->>'role',(x->>'contribution')::numeric from replacement_additions r join public.exercises e on e.slug=r.entry->>'slug' cross join lateral jsonb_array_elements(r.entry->'muscles') x join public.muscle_groups m on m.slug=x->>'muscle';

create temporary table replacement_profiles(slug text primary key,replacement_family text,equipment_options jsonb,variant_group text) on commit drop;
update public.exercises e set replacement_family=p.replacement_family,equipment_options=p.equipment_options,variant_group=p.variant_group from replacement_profiles p where e.slug=p.slug;
-- Family and equipment eligibility are data-level candidate criteria. They do not
-- certify injury safety, strength-load equivalence, impact level or prescription compatibility.
commit;
